84			{"duplicate collected_at", `[{"node":"val-1","seq":1,"collected_at":"2026-10-01T11:59:00Z","collected_at":"2026-10-01T11:59:00Z","version":"1.0","height":1,"missed":0}]`},
85			{"duplicate version", `[{"node":"val-1","seq":1,"collected_at":"2026-10-01T11:59:00Z","version":"1.0","version":"2.0","height":1,"missed":0}]`},
86			{"duplicate via unicode escape", `[{"node":"val-1","seq":1,"collected_at":"2026-10-01T11:59:00Z","version":"1.0","height":1,"missed":0,"missed":1}]`},
87			{"duplicate via unicode escape reversed", `[{"node":"val-1","seq":1,"collected_at":"2026-10-01T11:59:00Z","version":"1.0","height":1,"missed":0,"missed":1}]`},
88		}
89		for _, tc := range cases {
90			t.Run(tc.name, func(t *testing.T) {
91				_, err := ParseHeartbeats([]byte(tc.input), testBase)
92				if err == nil {
93					t.Errorf("expected error for %s, got nil", tc.name)
94				}
95			})
96		}
97	}
98	
99	func TestValidateHeartbeat(t *testing.T) {
100		receive := testBase
101		valid := hb("n1", 1, receive.Add(-time.Minute), "1.0", 10, 0)
102		if err := ValidateHeartbeat(valid, receive); err != nil {
103			t.Errorf("valid record rejected: %v", err)
104		}
105		// Boundary: collected exactly at receive time is allowed.
106		exact := hb("n1", 1, receive, "1.0", 10, 0)
107		if err := ValidateHeartbeat(exact, receive); err != nil {
108			t.Errorf("collected_at == receive_time should be allowed: %v", err)
109		}
110		// Boundary: height 0 and missed 0 are allowed.
111		zero := hb("n1", 1, receive.Add(-time.Minute), "1.0", 0, 0)
112		if err := ValidateHeartbeat(zero, receive); err != nil {
113			t.Errorf("zero height/missed should be allowed: %v", err)
114		}
115		// Future collection time rejected.
116		future := hb("n1", 1, receive.Add(time.Second), "1.0", 10, 0)
117		if err := ValidateHeartbeat(future, receive); err == nil {
118			t.Errorf("future collected_at should be rejected")
119		}
120	}
121	
122	func TestSubmitNewAndDuplicate(t *testing.T) {
123		store, err := OpenStore(t.TempDir())
124		if err != nil {
125			t.Fatal(err)
126		}
127		receive := testBase
128		batch := []Heartbeat{
129			hb("n1", 1, receive.Add(-2*time.Minute), "1.0", 100, 0),
130			hb("n1", 2, receive.Add(-time.Minute), "1.0", 101, 0),
131			hb("n2", 5, receive.Add(-time.Minute), "2.0", 50, 3),
132		}
133		newC, dupC, err := store.Submit(batch, receive)
134		if err != nil {
135			t.Fatalf("submit failed: %v", err)
136		}
137		if newC != 3 || dupC != 0 {
138			t.Errorf("first submit: new=%d dup=%d, want 3/0", newC, dupC)
139		}
