301	func TestStoredInvalidVersionTextIsCorrupt(t *testing.T) {
302		cases := []struct {
303			name        string
304			versionJSON string // raw version token in the tampered file
305		}{
306			{"invalid UTF-8 byte", `"1.26.0-` + "\xff" + `"`},
307			{"unpaired high surrogate escape", `"1.26.0-` + bs + `uD83D"`},
308			{"unpaired low surrogate escape", `"1.26.0-` + bs + `uDE00"`},
309		}
310		for _, tc := range cases {
311			t.Run(tc.name, func(t *testing.T) {
312				dir := t.TempDir()
313				store, err := OpenStore(dir)
314				if err != nil {
315					t.Fatal(err)
316				}
317	
318				// Another node holds genuine data and keeps working throughout.
319				receive := testBase
320				if _, _, err := store.Submit([]Heartbeat{
321					hb("good", 1, receive.Add(-time.Minute), "1.26.0", 100, 0),
322				}, receive); err != nil {
323					t.Fatal(err)
324				}
325	
326				path := store.nodePath("bad")
327				tampered := `[{"node":"bad","seq":1,"collected_at":"2026-10-01T11:59:00Z","version":` + tc.versionJSON + `,"height":100,"missed":0}]`
328				tamperedFile(t, path, tampered)
329				before, err := os.ReadFile(path)
330				if err != nil {
331					t.Fatal(err)
332				}
333	
334				// The file is refused as corrupt even though its checksum matches
335				// the replacement-char interpretation.
336				if _, err := loadNodeFile(path); err == nil || !IsCorrupt(err) {
337					t.Fatalf("read must report corruption, got %v", err)
338				} else if !strings.Contains(err.Error(), "record 1") || !strings.Contains(err.Error(), "version") {
339					t.Errorf("error must name record 1 and the version field, got: %v", err)
