	if err != nil || len(hist) != 1 {
		t.Fatalf("the two spellings must not split the node: %+v err=%v", hist, err)
	}
}

func TestLongNodeIDHistoryOrderHealthSelectionAndBaseline(t *testing.T) {
	store, err := OpenStore(t.TempDir())
